pub(crate) fn sv_unit_chain(entries: &[SvEntry], value: &mut Vec<i64>, lits: &[u32], hints: &[u32], touched: &mut Vec<u32>) -> String {
    for l in lits.iter() {
        let l = nikaia_std::num::value(l);
        sv_assign(value, l ^ 1u32);
        touched.push(l);
    }
    for h in hints.iter() {
        let h = nikaia_std::num::value(h);
        let at = h as i64;
        if at >= entries.len() as i64 { return format!("hint {} is no earlier entry", h); }
        let clause = match nikaia_std::index::get(&entries, nikaia_std::index::at(at)) {
            SvEntry::Clause(c) => c,
            _ => return format!("hint {} is no clause", h),
        };
        let mut open: Vec<u32> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        for l in clause.iter() {
            let l = nikaia_std::num::value(l);
            let v = sv_value(&value, l);
            if v > 0 { return format!("hint {} is already true", h); }
            if v == 0 { open.push(l); }
        }
        if open.is_empty() { return String::from(""); }
        if open.len() > 1 { return format!("hint {} is not unit: {} literals open", h, open.len() as i64); }
        sv_assign(value, *unsafe { nikaia_std::proven::read(&open, (0) as usize) });
        touched.push(*unsafe { nikaia_std::proven::read(&open, (0) as usize) });
    }
    String::from("the hints end without a conflict")
}

pub(crate) fn sv_assign(value: &mut Vec<i64>, l: u32) {
    let at = (l / 2u32) as i64;
    { let __nikaia_stored = if l % 2u32 == 0u32 { 1 } else { -1 }; nikaia_std::index::set(&mut *value, nikaia_std::index::at(at), __nikaia_stored); }
}

pub(crate) fn sv_value(value: &[i64], l: u32) -> i64 {
    let v = *nikaia_std::index::get(&value, nikaia_std::index::at((l / 2u32) as i64));
    if l % 2u32 == 0u32 { v } else { -v }
}

pub(crate) fn sv_rel_text(rel: &SvRel) -> &'static str {
    match rel {
        SvRel::Le => "<=",
        SvRel::Lt => "<",
        SvRel::Eq => "=",
    }
}

